import json, sys
sys.stdout.reconfigure(encoding='utf-8')
rows = [l.rstrip('\n').split('\t') for l in open('kb/work/batch_ppl_3.tsv', encoding='utf-8')][1:]
K = {i + 1: r[0] for i, r in enumerate(rows)}
ART = {r[0]: r[7].split() for r in rows}
DATE = {}
for l in open('kb/work/articles.jsonl', encoding='utf-8'):
    a = json.loads(l); DATE[a['id']] = a['d']

ents = []
def E(slug, he, en, desc, kind, country=None, keys=(), alt=None, role=None, pref='ppl'):
    e = {'id': slug if ':' in slug else f'{pref}:{slug}', 'he': he, 'en': en}
    if alt: e['en_alt'] = alt
    e['desc'] = desc
    if role: e['role'] = role
    e['kind'] = kind
    if country: e['country'] = country
    e['keys'] = [K[k] if isinstance(k, int) else k for k in keys]
    ents.append(e)

